// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *SalesReceivablesSetup) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, SalesReceivablesSetupTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (primary_key)`,
		fmt.Sprintf("%s$Sales_Receivables_Setup$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	var keys []sift.Key
	for _, spec := range salesReceivablesSetupSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, SalesReceivablesSetupTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, SalesReceivablesSetupTableName, keys)
}

// salesReceivablesSetupSIFTSpecs are the table's keys with sum_index_fields
func salesReceivablesSetupSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *SalesReceivablesSetup) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, SalesReceivablesSetupTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range salesReceivablesSetupSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, SalesReceivablesSetupTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: SalesReceivablesSetupTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, SalesReceivablesSetupTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

